import React, { useEffect, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import './Header.css';

function Header() {
  const [username, setUsername] = useState(localStorage.getItem('username'));
  const navigate = useNavigate();

  useEffect(() => {
    // Update username when localStorage changes
    const handleStorageChange = () => {
      setUsername(localStorage.getItem('username'));
    };

    window.addEventListener('storage', handleStorageChange);
    return () => window.removeEventListener('storage', handleStorageChange);
  }, []);

  const handleLogout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('username');
    localStorage.removeItem('email');
    setUsername(null);
    navigate('/login');
  };

  return (
    <header className="header">
      <h1 className="logo">Forum App</h1>
      <nav>
        {username ? (
          <div className="user-dropdown">
            <span className="username">Bun venit, {username}!</span>
            <button className="logout-btn" onClick={handleLogout}>Delogare</button>
          </div>
        ) : (
          <>
            <Link to="/login">Autentificare</Link>
            <Link to="/register">Înregistrare</Link>
          </>
        )}
      </nav>
    </header>
  );
}

export default Header;
